66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
75	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
76	     * and a dotted domain (e.g. {@code not-an-email}).
77	     */
78	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
79	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
80	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
81	
82	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
83	    private static final String DEFAULT_COUNTRY_CODE = "61";
84	
85	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
86	    private static final int MAX_OWNERS_PER_CITY = 50;
87	
88	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
89	    private static final int MAX_OWNERS_PER_DAY = 100;
90	
91	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
92	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
93	
94	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
95	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
96	
97	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
98	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
99	
100	    /**
101	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
102	     * is listed here must carry exactly the required number of national digits, otherwise it is
103	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
104	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
105	     */
106	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
107	        "61", 9,
108	        "1", 10);
109	
110	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
111	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
112	        "ST", "STREET",
113	        "RD", "ROAD",
114	        "AVE", "AVENUE");
115	
116	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
117	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
118	
119	    private final ClinicService clinicService;
120	
121	    private final OwnerMapper ownerMapper;
122	
123	    private final PetMapper petMapper;
124	
125	    private final VisitMapper visitMapper;
126	
127	    public OwnerRestControllerV1(ClinicService clinicService,
128	                                 OwnerMapper ownerMapper,
129	                                 PetMapper petMapper,
130	                                 VisitMapper visitMapper) {
131	        this.clinicService = clinicService;
132	        this.ownerMapper = ownerMapper;
133	        this.petMapper = petMapper;
134	        this.visitMapper = visitMapper;
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
140	        Collection<Owner> owners;
141	        if (lastName != null) {
142	            owners = this.clinicService.findOwnerByLastName(lastName);
143	        } else {
144	            owners = this.clinicService.findAllOwners();
145	        }
146	        if (owners.isEmpty()) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        owners.forEach(this::populateHouseholdSize);
150	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        populateHouseholdSize(owner);
161	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
167	        List<String> missingFields = new ArrayList<>();
168	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
169	            missingFields.add("firstName");
170	        }
171	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
172	            missingFields.add("lastName");
173	        }
174	        // Normalize the address up front; the required-field check rejects it when it is blank
175	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
176	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
177	        if (!StringUtils.hasText(normalizedAddress)) {
178	            missingFields.add("address");
179	        }
180	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
181	            missingFields.add("city");
182	        }
183	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
184	            missingFields.add("telephone");
185	        }
186	        if (!missingFields.isEmpty()) {
187	            throw new InvalidRequestException(missingFields);
188	        }
189	        HttpHeaders headers = new HttpHeaders();
190	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
191	        // Store (and later return) the normalized address computed above.
192	        owner.setAddress(normalizedAddress);
193	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
194	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
195	        owner.setTelephone(normalizedTelephone);
196	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
197	        owner.setEmail(normalizeEmail(owner.getEmail()));
198	        // Default the (optional) registration date to the server's current date when none was supplied.
199	        if (owner.getRegistrationDate() == null) {
200	            owner.setRegistrationDate(LocalDate.now());
201	        }
202	        // The effective registration date must fall on a business day: when it lands on a Saturday or
203	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
204	        // derived from the registration date below (daily create-limit, membership number) uses this
205	        // adjusted date.
206	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
207	        // Reject the request once the maximum number of owners for the owner's registration day has
208	        // been reached (100 or more owners already created on that date).
209	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
210	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
211	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
212	        }
213	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
214	        // owner's registration day at the moment this owner was created; otherwise clear it.
215	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
216	        // Reject the request when the owner's city has already reached its owner capacity.
217	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
218	            throw new CityCapacityException(owner.getCity());
219	        }
220	        // Reject the request if the E.164 telephone is already used by another owner.
221	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
222	            throw new DuplicateTelephoneException(normalizedTelephone);
223	        }
224	        // Reject the request if the (normalized, lower-cased) email is already used by another owner.
225	        if (owner.getEmail() != null && isEmailInUse(owner.getEmail())) {
226	            throw new DuplicateEmailException(owner.getEmail());
227	        }
228	        // Reject the request if another owner already shares the same last name and address
229	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
230	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
231	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
232	        // every existing member that does not yet carry it.
233	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
234	        if (!householdMembers.isEmpty()) {
235	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
236	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
237	            }
238	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
239	            owner.setHouseholdId(householdId);
240	            for (Owner member : householdMembers) {
241	                if (!householdId.equals(member.getHouseholdId())) {
242	                    member.setHouseholdId(householdId);
243	                    this.clinicService.saveOwner(member);
244	                }
245	            }
246	        }
247	        // Record how many existing owners already share this first name and last name
248	        // (compared case-insensitively) before this owner is created.
249	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
250	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
251	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
252	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
253	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
254	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
255	        this.clinicService.saveOwner(owner);
256	        populateHouseholdSize(owner);
257	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
258	        // Emit an audit line carrying the new owner's id, customer code, registration date
259	        // and numeric membership level.
260	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
261	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
262	            ownerDto.getMembershipLevel());
263	        headers.setLocation(UriComponentsBuilder.newInstance()
264	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
265	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
271	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
272	        if (currentOwner == null) {
273	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	        }
275	        currentOwner.setAddress(ownerFieldsDto.getAddress());
276	        currentOwner.setCity(ownerFieldsDto.getCity());
277	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
278	        currentOwner.setLastName(ownerFieldsDto.getLastName());
279	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
280	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
281	        this.clinicService.saveOwner(currentOwner);
282	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
283	    }
284	
285	    /**
286	     * Populate the owner's household size: the number of owners sharing this owner's
287	     * {@code householdId} (including the owner itself). An owner with no household is a household
288	     * of one.
289	     *
290	     * @param owner the owner whose household size should be computed and set
291	     */
292	    private void populateHouseholdSize(Owner owner) {
293	        String householdId = owner.getHouseholdId();
294	        if (!StringUtils.hasText(householdId)) {
295	            owner.setHouseholdSize(1);
296	            return;
297	        }
298	        int size = (int) this.clinicService.findAllOwners().stream()
299	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
300	            .count();
301	        owner.setHouseholdSize(size);
302	    }
303	
304	    /**
305	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
306	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
307	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
308	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
309	     *
310	     * @param city     the owner's city
311	     * @param lastName the owner's last name
312	     * @return the generated customer code
313	     */
314	    private String generateCustomerCode(String city, String lastName) {
315	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
316	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
317	        String normalizedCity = normalizeForComparison(city);
318	        int sequence = (int) this.clinicService.findAllOwners().stream()
319	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
320	            .count() + 1;
321	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
322	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
323	    }
324	
325	    /**
326	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
327	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
328	     * that is stored, returned and used for every value derived from it.
329	     *
330	     * @param date the effective registration date (supplied or defaulted)
331	     * @return the same date when it is a weekday, otherwise the next Monday
332	     */
333	    private LocalDate rollToBusinessDay(LocalDate date) {
334	        DayOfWeek dayOfWeek = date.getDayOfWeek();
335	        if (dayOfWeek == DayOfWeek.SATURDAY) {
336	            return date.plusDays(2);
337	        }
338	        if (dayOfWeek == DayOfWeek.SUNDAY) {
339	            return date.plusDays(1);
340	        }
341	        return date;
342	    }
343	
344	    /**
345	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
346	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
347	     *
348	     * @param customerCode     the owner's already-assigned customer code
349	     * @param registrationDate the owner's registration date
350	     * @return the generated membership number
351	     */
352	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
353	        String yy = String.format("%02d", registrationDate.getYear() % 100);
354	        return String.format("%s-M%s", customerCode, yy);
355	    }
356	
357	    /**
358	     * Count the existing owners that share the given first name and last name, comparing each
359	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
360	     * yet persisted, so it is not included in the count.
361	     *
362	     * @param firstName the incoming owner's first name
363	     * @param lastName  the incoming owner's last name
364	     * @return the number of existing namesakes
365	     */
366	    private int countNamesakes(String firstName, String lastName) {
367	        String normalizedFirstName = normalizeForComparison(firstName);
368	        String normalizedLastName = normalizeForComparison(lastName);
369	        return (int) this.clinicService.findAllOwners().stream()
370	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
371	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
372	            .count();
373	    }
374	
375	    /**
376	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
377	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
378	     *
379	     * @param city the incoming owner's city
380	     * @return the number of existing owners already in that city
381	     */
382	    private int countOwnersInCity(String city) {
383	        String normalizedCity = normalizeForComparison(city);
384	        return (int) this.clinicService.findAllOwners().stream()
385	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
386	            .count();
387	    }
388	
389	    /**
390	     * Count the existing owners whose registration date equals the given date. The incoming owner is
391	     * not yet persisted, so it is not included in the count.
392	     *
393	     * @param registrationDate the incoming owner's registration date
394	     * @return the number of existing owners already registered on that date
395	     */
396	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
397	        return (int) this.clinicService.findAllOwners().stream()
398	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
399	            .count();
400	    }
401	
402	    /**
403	     * Determine whether the given (already lower-cased) email is already used by any existing owner,
404	     * comparing case-insensitively. The incoming owner is not yet persisted, so it is not included.
405	     *
406	     * @param email the incoming owner's normalized email
407	     * @return {@code true} when another owner already uses that email
408	     */
409	    private boolean isEmailInUse(String email) {
410	        String normalizedEmail = email.toLowerCase(Locale.ROOT);
411	        return this.clinicService.findAllOwners().stream()
412	            .anyMatch(existing -> existing.getEmail() != null
413	                && existing.getEmail().toLowerCase(Locale.ROOT).equals(normalizedEmail));
414	    }
415	
416	    /**
417	     * Find the existing owners that live in the same household as the given values, i.e. those that
418	     * share both the last name and the address when each is compared case-insensitively with
419	     * collapsed whitespace.
420	     *
421	     * @param lastName the incoming owner's last name
422	     * @param address  the incoming owner's address
423	     * @return the matching existing owners (possibly empty)
424	     */
425	    private List<Owner> findHouseholdMembers(String lastName, String address) {
426	        String normalizedLastName = normalizeForComparison(lastName);
427	        String normalizedAddress = normalizeForComparison(address);
428	        return this.clinicService.findAllOwners().stream()
429	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
430	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
431	            .toList();
432	    }
433	
434	    /**
435	     * Generate a stable shared household identifier for the given last name and address. The value is
436	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
437	     * and address, so every owner joining the same household resolves to the same identifier. It is the
438	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
439	     *
440	     * @param lastName the household's last name
441	     * @param address  the household's address
442	     * @return the stable household identifier
443	     */
444	    private String generateHouseholdId(String lastName, String address) {
445	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
446	        try {
447	            byte[] digest = MessageDigest.getInstance("SHA-256")
448	                .digest(key.getBytes(StandardCharsets.UTF_8));
449	            StringBuilder sb = new StringBuilder(digest.length * 2);
450	            for (byte b : digest) {
451	                sb.append(String.format("%02x", b));
452	            }
453	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
454	        } catch (java.security.NoSuchAlgorithmException e) {
455	            throw new IllegalStateException("SHA-256 not available", e);
456	        }
457	    }
458	
459	    /**
460	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
461	     * single space, upper-case the result and expand common street-type abbreviations token by token
462	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
463	     * to the empty string. The result is the canonical form that is stored, returned and used for every
464	     * address comparison (household duplicate detection and the shared household id).
465	     *
466	     * @param address the raw address, may be {@code null}
467	     * @return the normalized address
468	     */
469	    private String normalizeAddress(String address) {
470	        if (address == null) {
471	            return "";
472	        }
473	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
474	        if (collapsed.isEmpty()) {
475	            return "";
476	        }
477	        String[] tokens = collapsed.split(" ");
478	        StringBuilder sb = new StringBuilder(collapsed.length());
479	        for (int i = 0; i < tokens.length; i++) {
480	            if (i > 0) {
481	                sb.append(' ');
482	            }
483	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
484	        }
485	        return sb.toString();
486	    }
487	
488	    /**
489	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
490	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
491	     *
492	     * @param value the raw value, may be {@code null}
493	     * @return the normalized value
494	     */
495	    private String normalizeForComparison(String value) {
496	        if (value == null) {
497	            return "";
498	        }
499	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
500	    }
501	
502	    /**
503	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
504	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
505	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
506	     * is returned lower-cased.
507	     *
508	     * @param email the raw email from the request payload, may be {@code null}
509	     * @return the lower-cased email, or {@code null} when none was provided
510	     */
511	    private String normalizeEmail(String email) {
512	        if (!StringUtils.hasText(email)) {
513	            return null;
514	        }
515	        if (!EMAIL_PATTERN.matcher(email).matches()) {
516	            throw new InvalidRequestException(List.of("email"));
517	        }
518	        return email.toLowerCase(Locale.ROOT);
519	    }
520	
521	    /**
522	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
523	     * already carries a leading '+' keeps its country code; otherwise the default country code
524	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
525	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
526	     * is thrown (mapped to 400 Bad Request).
527	     *
528	     * @param telephone the raw telephone from the request payload
529	     * @return the E.164 string (e.g. {@code +61412345678})
530	     */
531	    private String normalizeTelephone(String telephone) {
532	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
533	        String candidate;
534	        if (cleaned.startsWith("+")) {
535	            candidate = cleaned;
536	        } else {
537	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
538	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
539	        }
540	        if (!E164_PATTERN.matcher(candidate).matches()) {
541	            throw new InvalidRequestException(List.of("telephone"));
542	        }
543	        // For country codes with a known fixed national-number length, reject a candidate whose
544	        // national digits (everything after the '+' and the country code) do not match that length.
545	        String digits = candidate.substring(1);
546	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
547	            String countryCode = entry.getKey();
548	            if (digits.startsWith(countryCode)) {
549	                int nationalLength = digits.length() - countryCode.length();
550	                if (nationalLength != entry.getValue()) {
551	                    throw new InvalidRequestException(List.of("telephone"));
552	                }
553	                break;
554	            }
555	        }
556	        return candidate;
557	    }
558	
559	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
560	    @Transactional
561	    @Override
562	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
563	        Owner owner = this.clinicService.findOwnerById(ownerId);
564	        if (owner == null) {
565	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
566	        }
567	        this.clinicService.deleteOwner(owner);
568	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
569	    }
570	
571	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
572	    @Override
573	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
574	        Owner owner = this.clinicService.findOwnerById(ownerId);
575	        if (owner == null) {
576	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
577	        }
578	        HttpHeaders headers = new HttpHeaders();
579	        Pet pet = petMapper.toPet(petFieldsDto);
580	        owner.setId(ownerId);
581	        pet.setOwner(owner);
582	        pet.getType().setName(null);
583	        this.clinicService.savePet(pet);
584	        PetDto petDto = petMapper.toPetDto(pet);
585	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
586	            .buildAndExpand(pet.getId()).toUri());
587	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
588	    }
589	
590	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
591	    @Override
592	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
593	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
594	        if (currentOwner != null) {
595	            Pet currentPet = this.clinicService.findPetById(petId);
596	            if (currentPet != null) {
597	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
598	                currentPet.setName(petFieldsDto.getName());
599	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
600	                this.clinicService.savePet(currentPet);
601	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
602	            }
603	        }
604	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
605	    }
606	
607	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
608	    @Override
609	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
610	        HttpHeaders headers = new HttpHeaders();
611	        Visit visit = visitMapper.toVisit(visitFieldsDto);
612	        Pet pet = new Pet();
613	        pet.setId(petId);
614	        visit.setPet(pet);
615	        this.clinicService.saveVisit(visit);
616	        VisitDto visitDto = visitMapper.toVisitDto(visit);
617	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
618	            .buildAndExpand(visit.getId()).toUri());
619	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
620	    }
621	
622	
623	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
624	    @Override
625	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
626	        Owner owner = this.clinicService.findOwnerById(ownerId);
627	        if (owner != null) {
628	            Pet pet = owner.getPet(petId);
629	            if (pet != null) {
630	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
631	            }
632	        }
633	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
634	    }
635	}
