public enum ContactPreferenceEnum {
  EMAIL("EMAIL"),

  PHONE("PHONE");

  private final String value;

  ContactPreferenceEnum(String value) {
    this.value = value;
  }

  @JsonValue
  public String getValue() {
    return value;
  }

  @Override
  public String toString() {
    return String.valueOf(value);
  }

  @JsonCreator
  public static ContactPreferenceEnum fromValue(String value) {
    for (ContactPreferenceEnum b : ContactPreferenceEnum.values()) {
      if (b.value.equals(value)) {
        return b;
      }
    }
    throw new IllegalArgumentException("Unexpected value '" + value + "'");
  }
